// Civic Story page logic. All member and seat facts come from window.REPMAP_STORY_DATA
// (story-data.js, generated by scripts/story-data.mjs from public/data at build time)
// and the election date from /data/elections/index.json. Nothing here is hand-typed
// member data (R-16, R-62). Links use the app's URL scheme: /, /?zip=, /?rep=, ...
(function () {
  "use strict";

  var ART = window.REPMAP_ATLAS_DATA || { nc116: [], nc119: [], heroStates: {} };
  var SD = window.REPMAP_STORY_DATA;
  if (!SD || !SD.anchors || !SD.anchors.length) {
    if (window.ScrollCraft) window.ScrollCraft.mount(document.body);
    return;
  }

  var STATE_NAMES = {
    AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California", CO: "Colorado",
    CT: "Connecticut", DE: "Delaware", FL: "Florida", GA: "Georgia", HI: "Hawaii", ID: "Idaho",
    IL: "Illinois", IN: "Indiana", IA: "Iowa", KS: "Kansas", KY: "Kentucky", LA: "Louisiana",
    ME: "Maine", MD: "Maryland", MA: "Massachusetts", MI: "Michigan", MN: "Minnesota",
    MS: "Mississippi", MO: "Missouri", MT: "Montana", NE: "Nebraska", NV: "Nevada",
    NH: "New Hampshire", NJ: "New Jersey", NM: "New Mexico", NY: "New York", NC: "North Carolina",
    ND: "North Dakota", OH: "Ohio", OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania",
    RI: "Rhode Island", SC: "South Carolina", SD: "South Dakota", TN: "Tennessee", TX: "Texas",
    UT: "Utah", VT: "Vermont", VA: "Virginia", WA: "Washington", WV: "West Virginia",
    WI: "Wisconsin", WY: "Wyoming", DC: "District of Columbia"
  };
  var PARTY_LETTER = { democrat: "D", republican: "R", independent: "I" };
  var PARTY_ADJ = { democrat: "Democratic", republican: "Republican", independent: "independent" };
  var PARTY_PLURAL = { democrat: "Democrats", republican: "Republicans", independent: "independents" };

  var anchorsByZip = {};
  SD.anchors.forEach(function (a) { anchorsByZip[a.zip] = a; });
  var M = SD.members;

  // ------------------------------------------------------------ helpers --
  function $(id) { return document.getElementById(id); }
  function setText(id, text) { var el = $(id); if (el) el.textContent = text; }
  function setHref(id, href) { var el = $(id); if (el) el.setAttribute("href", href); }
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function party(p) { return PARTY_LETTER[p] ? p : "independent"; }
  function partyName(p) { p = party(p); return p.charAt(0).toUpperCase() + p.slice(1); }
  function stateName(code) { return STATE_NAMES[code] || code; }
  function seatCode(a) { return a.state + "-" + a.district; }
  function districtLabel(a) { return a.district === 0 ? "at-large district" : "District " + a.district; }
  function ordinal(n) {
    var s = ["th", "st", "nd", "rd"], v = n % 100;
    return n + (s[(v - 20) % 10] || s[v] || s[0]);
  }
  function listJoin(items) {
    if (items.length <= 1) return items.join("");
    return items.slice(0, -1).join(", ") + " and " + items[items.length - 1];
  }
  function fmt(n) { return Number(n).toLocaleString("en-US"); }
  function cityOf(zip) {
    var chip = document.querySelector('.zip-chip[data-zip="' + zip + '"]');
    return chip ? chip.getAttribute("data-city") : "";
  }
  function shortCommittee(name) {
    return name.replace(/^(House|Senate|Joint) Committee on (the )?/, "$1 ").replace(/^Joint Committee of Congress on the /, "Joint ");
  }
  function repUrl(id) { return "/?rep=" + encodeURIComponent(id); }
  function zipUrl(zip) { return "/?zip=" + encodeURIComponent(zip); }
  function committeeUrl(name) { return "/?committee=" + encodeURIComponent(name); }

  // ------------------------------------------------------- static binds --
  (function bindStatic() {
    var asOf = SD.generatedAt ? new Date(SD.generatedAt) : null;
    if (asOf && !isNaN(asOf)) {
      var asOfText = asOf.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
      document.querySelectorAll('[data-bind="data-asof"]').forEach(function (el) { el.textContent = " · Data as of " + asOfText; });
      var y = asOf.getUTCFullYear();
      var congress = Math.floor((y - 1789) / 2) + 1;
      if (y % 2 === 1 && asOf.getUTCMonth() === 0 && asOf.getUTCDate() < 3) congress -= 1;
      document.querySelectorAll('[data-bind="congress-suffix"]').forEach(function (el) { el.textContent = " · " + ordinal(congress) + " Congress"; });
    }

    var c = SD.counts;
    document.querySelectorAll("[data-bind-count]").forEach(function (el) {
      var n = c[el.getAttribute("data-bind-count")];
      if (n == null) { var card = el.closest(".scale-card"); if (card) card.hidden = true; return; }
      el.textContent = fmt(n);
      el.setAttribute("data-sc-count", "0 " + fmt(n));
      el.setAttribute("data-sc-count-at", "0.05 0.45");
    });
    setText("scale-members-meta",
      fmt(c.house) + " House seats (" + fmt(c.houseVoting) + " voting, " + fmt(c.delegates) +
      (c.delegates === 1 ? " non-voting delegate" : " non-voting delegates") + ") and " + fmt(c.senate) + " senators");

    document.querySelectorAll(".zip-chip").forEach(function (btn) {
      var a = anchorsByZip[btn.dataset.zip];
      if (!a) { btn.hidden = true; return; }
      btn.innerHTML = esc(a.zip) + '<span class="zip-chip__city"> · ' + esc(btn.dataset.city) + "</span> · " + esc(seatCode(a));
    });
  })();

  var activeZip = SD.anchors[0].zip;
  var ncManualMode = "auto";
  var reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  // ------------------------------------------------------- hero geometry --
  function renderHeroGeometry(zip) {
    var a = anchorsByZip[zip];
    var geo = ART.heroStates[zip];
    var stateSvg = $("hero-state-svg");
    var focalSvg = $("hero-focal-svg");
    if (!stateSvg || !focalSvg) return;
    if (!geo || !a) { stateSvg.innerHTML = ""; focalSvg.innerHTML = ""; return; }
    var parties = (SD.districtParty && SD.districtParty[a.state]) || {};

    var markup = "";
    geo.statePaths.forEach(function (item) {
      var num = Number(item.num);
      var focal = num === a.district;
      var cls = "d-shape " + (focal ? "d-shape--focal" : "d-shape--" + party(parties[num] || item.party));
      markup += '<path class="' + cls + '" d="' + item.d + '"/>';
    });
    stateSvg.innerHTML = markup;

    // The cut-out art was drawn for one district; only show it if that is still this ZIP's district.
    var fc = geo.focalCutout;
    if (fc && fc.d && Number(geo.district) === a.district) {
      focalSvg.innerHTML =
        '<path class="d-shape d-shape--lens" d="' + fc.d + '"/>' +
        '<circle class="focal-dot" cx="' + fc.cx + '" cy="' + fc.cy + '" r="5.5"/>' +
        '<circle class="focal-ring" cx="' + fc.cx + '" cy="' + fc.cy + '" r="16"/>';
    } else {
      focalSvg.innerHTML = "";
    }
  }

  // ------------------------------------------------------- NC redistricting --
  function partyCounts(list) {
    var out = { democrat: 0, republican: 0, independent: 0 };
    list.forEach(function (p) { out[party(p)] += 1; });
    return out;
  }
  function countsText(n, counts) {
    var bits = [];
    ["democrat", "republican", "independent"].forEach(function (p) { if (counts[p]) bits.push(counts[p] + " " + PARTY_LETTER[p]); });
    return n + " districts · " + bits.join(", ");
  }

  function renderNorthCarolina() {
    var svg116 = $("nc-116-svg"), svg119 = $("nc-119-svg");
    if (!svg116 || !svg119) return;
    var nowParty = (SD.districtParty && SD.districtParty.NC) || {};
    var n116 = ART.nc116.length, n119 = ART.nc119.length;

    var m116 = "";
    ART.nc116.forEach(function (d) {
      m116 += '<path class="d-shape d-shape--past d-shape--' + party(d.party) + '" d="' + d.d + '"/>';
      m116 += '<text class="nc-label" x="' + d.cx + '" y="' + d.cy + '" text-anchor="middle">' + d.num + "</text>";
    });
    svg116.innerHTML = m116;

    // Opaque ground so the older map's labels don't show through the newer one.
    var m119 = '<rect class="nc-ground" width="860" height="380"/>';
    ART.nc119.forEach(function (d) {
      var isNew = d.num > n116;
      var cls = isNew ? "d-shape d-shape--focal" : "d-shape d-shape--" + party(nowParty[d.num] || d.party);
      m119 += '<path class="' + cls + '" d="' + d.d + '"/>';
      m119 += '<text class="nc-label" x="' + d.cx + '" y="' + d.cy + '" text-anchor="middle">' + d.num + (isNew ? " (new)" : "") + "</text>";
    });
    svg119.innerHTML = m119;

    var then = partyCounts(ART.nc116.map(function (d) { return d.party; }));
    var nowNums = Object.keys(nowParty).map(Number).sort(function (x, y) { return x - y; });
    var now = partyCounts(nowNums.map(function (k) { return nowParty[k]; }));
    var seatsNow = nowNums.length || n119;

    setText("nc-epoch-readout", "North Carolina · " + n116 + " seats in the 116th Congress → " + seatsNow + " today");
    setText("nc-then", countsText(n116, then));
    setText("nc-now", countsText(seatsNow, now));
    var diff = seatsNow - n116;
    setText("nc-shift-metric", diff === 0 ? "Same number of seats" : (diff > 0 ? "+" : "") + diff + (Math.abs(diff) === 1 ? " seat" : " seats") + " after the 2020 Census");

    setText("nc-beat1", "In the 116th Congress (2019–2021), North Carolina had " + n116 + " House districts. Scroll to sweep from those lines to the 119th Congress map.");
    setText("nc-beat2", diff > 0
      ? "After the 2020 Census, North Carolina gained a " + ordinal(seatsNow) + " House seat, and its district lines have been redrawn since."
      : "North Carolina's district lines have been redrawn since the 116th Congress.");

    var order = ["republican", "democrat", "independent"].filter(function (p) { return now[p]; })
      .sort(function (x, y) { return now[y] - now[x]; });
    setText("nc-beat3-title", order.map(function (p) {
      return now[p] + " " + PARTY_ADJ[p] + (now[p] === 1 ? " seat." : " seats.");
    }).join(" ").replace(/^independent/, "Independent"));
    var minority = order[order.length - 1];
    var majority = order[0];
    if (order.length > 1) {
      var held = nowNums.filter(function (k) { return party(nowParty[k]) === minority; }).map(function (k) { return "NC-" + k; });
      setText("nc-beat3", "Today " + PARTY_PLURAL[minority] + " hold " + listJoin(held) + ", and " + PARTY_PLURAL[majority] +
        " hold the other " + now[majority] + ". Open District history to compare old and new lines in any state.");
    } else {
      setText("nc-beat3", "Open District history to compare old and new lines in any state.");
    }
  }

  // ------------------------------------------------------- delegation rail --
  function dossierCard(m, opts) {
    var seat = m.chamber === "senate"
      ? "U.S. Senate · " + stateName(m.state)
      : "U.S. House · " + stateName(m.state) + " " + (m.district === 0 ? "at-large" : "District " + m.district);
    var comms = m.committees.length
      ? '<ul class="dossier-committees" aria-label="Committees">' + m.committees.map(function (c) {
          return '<li class="dossier-comm-chip">' + esc(shortCommittee(c)) + "</li>";
        }).join("") + "</ul>"
      : '<p class="dossier-card__seat">No committee assignments listed.</p>';
    var contact = [m.room, m.phone].filter(Boolean).map(esc).join(" · ");
    return (
      '<article class="dossier-card' + (opts.active ? " dossier-card--active" : "") + '">' +
        "<div>" +
          '<div class="dossier-card__top"><div>' +
            '<div class="dossier-card__id">' + esc(opts.tag) + "</div>" +
            '<h3 class="dossier-card__name">' + esc(m.name) + "</h3>" +
            '<div class="dossier-card__seat">' + esc(seat) + "</div>" +
          "</div>" +
          '<span class="party-pill party-pill--' + party(m.party) + '">' + partyName(m.party) + "</span></div>" +
        "</div>" +
        '<dl class="dossier-metrics">' +
          "<div><dt>Committees</dt><dd>" + m.committees.length + "</dd></div>" +
          "<div><dt>Subcommittees</dt><dd>" + m.subcommittees + "</dd></div>" +
          "<div><dt>Seat next up</dt><dd>" + (m.nextElection || "–") + "</dd></div>" +
        "</dl>" +
        comms +
        '<div class="dossier-card__footer"><span>' + contact + "</span>" +
          '<a class="dossier-link" href="' + repUrl(m.id) + '">Open ' + esc(m.name) + " on the map</a></div>" +
      "</article>"
    );
  }

  function renderRail(a) {
    var rail = $("delegation-rail");
    if (!rail) return;
    var html = dossierCard(M[a.house], { active: true, tag: "ZIP " + a.zip + " · " + seatCode(a) });
    a.senators.forEach(function (id) { html += dossierCard(M[id], { tag: "ZIP " + a.zip + " · " + stateName(a.state) }); });
    SD.anchors.forEach(function (o) {
      if (o.zip !== a.zip) html += dossierCard(M[o.house], { tag: "ZIP " + o.zip + " · " + seatCode(o) });
    });
    rail.innerHTML = html;
  }

  // ------------------------------------------------------- committees --
  var hubs = (function () {
    var tally = {};
    SD.anchors.forEach(function (a) {
      M[a.house].committees.forEach(function (c) { (tally[c] = tally[c] || []).push(a.house); });
    });
    var list = Object.keys(tally).map(function (c) { return { name: c, members: tally[c] }; })
      .sort(function (x, y) { return y.members.length - x.members.length || x.name.localeCompare(y.name); });
    var shared = list.filter(function (h) { return h.members.length > 1; });
    return (shared.length >= 3 ? shared : list).slice(0, 5);
  })();
  var activeComm = "all";

  function renderCommittees() {
    var bar = $("comm-filter-bar"), rows = $("comm-rows");
    if (!bar || !rows) return;
    bar.innerHTML = '<button type="button" class="comm-filter-btn" data-comm="all" aria-pressed="true">All shown</button>' +
      hubs.map(function (h) {
        return '<button type="button" class="comm-filter-btn" data-comm="' + esc(h.name) + '" aria-pressed="false">' +
          esc(shortCommittee(h.name).replace(/^(House|Senate|Joint) /, "")) + "</button>";
      }).join("");
    rows.innerHTML = hubs.map(function (h) {
      return '<li class="comm-row" data-comm="' + esc(h.name) + '">' +
        '<div class="comm-row__name">' + esc(shortCommittee(h.name)) +
          '<span class="comm-row__count">' + h.members.length + (h.members.length === 1 ? " member shown" : " members shown") + "</span></div>" +
        '<ul class="comm-row__members">' + h.members.map(function (id) {
          var m = M[id];
          var a = SD.anchors.filter(function (x) { return x.house === id; })[0];
          return '<li class="member-tag member-tag--' + party(m.party) + '">' + esc(m.name) +
            " <b>(" + PARTY_LETTER[party(m.party)] + ")</b> · " + esc(seatCode(a)) + "</li>";
        }).join("") + "</ul></li>";
    }).join("");
    bar.querySelectorAll(".comm-filter-btn").forEach(function (btn) {
      btn.addEventListener("click", function () { selectCommittee(btn.getAttribute("data-comm")); });
    });
    selectCommittee("all");
  }

  function selectCommittee(comm) {
    activeComm = comm;
    document.querySelectorAll(".comm-filter-btn").forEach(function (b) {
      b.setAttribute("aria-pressed", b.getAttribute("data-comm") === comm ? "true" : "false");
    });
    document.querySelectorAll(".comm-row").forEach(function (row) {
      var match = comm === "all" || row.getAttribute("data-comm") === comm;
      row.setAttribute("data-dim", match ? "false" : "true");
      row.setAttribute("data-hit", match && comm !== "all" ? "true" : "false");
    });
    var target = comm === "all" ? (hubs[0] && hubs[0].name) : comm;
    if (target) {
      setHref("comm-launch-link", committeeUrl(target));
      setHref("close-comm-card", committeeUrl(target));
    }
    if (comm === "all") {
      setText("comm-status-readout", hubs.length + " committees shared by the House members for these " + SD.anchors.length +
        " ZIPs. The full data lists " + fmt(SD.counts.committees) + " committees across " + fmt(SD.counts.members) + " members.");
    } else {
      var h = hubs.filter(function (x) { return x.name === comm; })[0];
      setText("comm-status-readout", shortCommittee(comm) + ": " + (h ? h.members.length : 0) +
        " of these members. Open the committee graph to see everyone on it.");
    }
  }

  // ------------------------------------------------------- ZIP selection --
  function selectAnchorZip(zip) {
    var a = anchorsByZip[zip];
    if (!a) return;
    activeZip = zip;
    var h = M[a.house];
    var sens = a.senators.map(function (id) { return M[id]; });
    var city = cityOf(zip);
    var place = city ? city + ", " + a.state : stateName(a.state);

    document.querySelectorAll(".zip-chip").forEach(function (btn) {
      btn.setAttribute("aria-pressed", btn.dataset.zip === zip ? "true" : "false");
    });

    renderHeroGeometry(zip);

    setText("chrome-active-zip", "ZIP " + a.zip + " · " + seatCode(a));
    setText("hud-coord", Math.abs(a.lat).toFixed(4) + "° " + (a.lat >= 0 ? "N" : "S") + ", " + Math.abs(a.lng).toFixed(4) + "° " + (a.lng <= 0 ? "W" : "E"));
    setText("hud-district", stateName(a.state) + " · " + districtLabel(a));
    updateElectionChip();

    setText("beat2-sub", "ZIP " + a.zip + " in " + place + " is in " + stateName(a.state) + "'s " + districtLabel(a) +
      ". It is represented by one House member and " + (sens.length === 1 ? "one senator." : "two senators."));
    setHref("beat2-globe-link", zipUrl(a.zip));
    var list = $("hero-delegation-list");
    if (list) {
      var rows = [{ m: h, role: "U.S. House · " + seatCode(a) }].concat(sens.map(function (s) {
        return { m: s, role: "U.S. Senate · " + stateName(a.state) };
      }));
      list.innerHTML = rows.map(function (r) {
        return '<div class="hero-rep-row"><div>' +
          '<div class="hero-rep-row__name">' + esc(r.m.name) + "</div>" +
          '<div class="hero-rep-row__role">' + esc(r.role + (r.m.room ? " · " + r.m.room : "")) + "</div></div>" +
          '<span class="party-pill party-pill--' + party(r.m.party) + '">' + partyName(r.m.party) + "</span></div>";
      }).join("");
    }

    renderRail(a);
    var compare = sens.length ? "/?compare=" + encodeURIComponent(h.id) + "," + encodeURIComponent(sens[0].id) : repUrl(h.id);
    setHref("compare-link", compare);
    setHref("close-compare-card", compare);

    setText("close-readout-zip", a.zip + " · " + place);
    setText("close-readout-rep", seatCode(a) + " · " + h.name + " (" + PARTY_LETTER[party(h.party)] + ")");
    setText("close-readout-senate", sens.map(function (s) { return s.name + " (" + PARTY_LETTER[party(s.party)] + ")"; }).join(" · "));
    setHref("close-primary-cta", zipUrl(a.zip));
    setText("close-primary-cta", "Open ZIP " + a.zip + " on the map");
  }

  document.querySelectorAll(".zip-chip").forEach(function (btn) {
    btn.addEventListener("click", function () { selectAnchorZip(btn.dataset.zip); });
  });

  var zipForm = $("hero-zip-form");
  var zipInput = $("hero-zip-input");
  var zipStatus = $("hero-zip-status");
  if (zipForm && zipInput) {
    zipForm.addEventListener("submit", function (e) {
      var val = zipInput.value.trim();
      if (anchorsByZip[val]) {
        e.preventDefault();
        selectAnchorZip(val);
        if (zipStatus) zipStatus.textContent = "Showing ZIP " + val;
      } else if (/^\d{5}$/.test(val)) {
        if (zipStatus) zipStatus.textContent = "Opening ZIP " + val + " on the map…";
      } else {
        e.preventDefault();
        if (zipStatus) zipStatus.textContent = "Enter a 5-digit ZIP";
      }
    });
  }

  document.querySelectorAll(".redraw-mode-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      ncManualMode = btn.dataset.ncMode || "auto";
      document.querySelectorAll(".redraw-mode-btn").forEach(function (b) {
        b.setAttribute("aria-pressed", b === btn ? "true" : "false");
      });
      syncScrollDrivenStages();
    });
  });

  // ------------------------------------------------------- election chip --
  // Date and countdown come from the same index.json the app uses; the chip only
  // appears in the 60 days before an election (mirrors cycleInSeason in src/utils/elections.ts).
  var electionCycle = null;

  function daysUntil(iso) {
    var p = iso.split("-").map(Number);
    var now = new Date();
    var today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    return Math.round((new Date(p[0], p[1] - 1, p[2]).getTime() - today) / 86400000);
  }

  function updateElectionChip() {
    var chip = $("hero-election-chip");
    if (!chip || !electionCycle) return;
    var days = daysUntil(electionCycle.general_date);
    var p = electionCycle.general_date.split("-").map(Number);
    var date = new Date(p[0], p[1] - 1, p[2]).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
    var count = days === 0 ? "Election Day is today" : days === 1 ? "Tomorrow" : days + " days away";
    var name = electionCycle.label.replace(/^\d{4}\s*/, "");
    setText("hero-election-when", name + ": " + date + " · " + count);
    setText("hero-election-zip", activeZip);
    chip.setAttribute("href", zipUrl(activeZip));
    chip.hidden = false;
  }

  fetch("/data/elections/index.json")
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (index) {
      var cycles = (index && index.cycles) || [];
      var next = cycles.filter(function (c) { return daysUntil(c.general_date) >= 0; })[0];
      if (next && daysUntil(next.general_date) <= 60) {
        electionCycle = next;
        updateElectionChip();
      }
    })
    .catch(function () {}); // the reminder is optional; the Story works without it

  // ------------------------------------------------------- first paint --
  renderNorthCarolina();
  renderCommittees();
  selectAnchorZip(activeZip);

  // Mount the scroll engine only after the data-bound DOM exists, so it measures real content.
  window.ScrollCraft.mount(document.body);

  // ------------------------------------------------------- scroll stages --
  var atlasSec = $("atlas"), heroStage = $("hero-stage");
  var redrawSec = $("redraw"), redrawStage = $("redraw-stage");
  var enterSec = $("enter"), enterStage = $("enter-stage");
  var ncStack = $("nc-svg-stack"), ncCaliper = $("nc-caliper"), ncCaliperTag = $("nc-caliper-tag");

  function holdIf(el, cond) {
    if (cond) el.setAttribute("data-sc-verify-hold", "true");
    else el.removeAttribute("data-sc-verify-hold");
  }

  function syncScrollDrivenStages() {
    var isReduced = reducedMotion.matches;

    if (atlasSec && heroStage) {
      var p = parseFloat(atlasSec.style.getPropertyValue("--sc-p")) || 0;
      heroStage.style.setProperty("--hero-state-scale", isReduced ? "1" : (1 + p * 0.14).toFixed(3));
      heroStage.style.setProperty("--hero-focal-scale", isReduced ? "1" : (0.94 + p * 0.18).toFixed(3));
      heroStage.setAttribute("data-sc-verify-state", "hero:" + Math.round(p * 100) + ":" + activeZip);
      holdIf(heroStage, isReduced);
    }

    if (redrawSec && redrawStage && ncStack) {
      var rawP = parseFloat(redrawSec.style.getPropertyValue("--sc-p")) || 0;
      var morph;
      if (ncManualMode === "0") morph = 0;
      else if (ncManualMode === "1") morph = 1;
      else if (isReduced) morph = 0.65;
      else morph = Math.max(0.02, Math.min(0.98, rawP));

      var pct = Math.round(morph * 100);
      ncStack.style.setProperty("--nc-morph", morph.toFixed(3));
      if (ncCaliper) ncCaliper.style.left = pct + "%";
      if (ncCaliperTag) {
        ncCaliperTag.textContent = pct < 35 ? "116th Congress · " + pct + "%"
          : (pct < 72 ? "Sweeping · " + pct + "%" : "119th Congress · " + pct + "%");
      }
      redrawStage.setAttribute("data-sc-verify-state", "nc:caliper:" + pct);
      holdIf(redrawStage, isReduced);
    }

    if (enterSec && enterStage) {
      var ep = parseFloat(enterSec.style.getPropertyValue("--sc-p")) || 0;
      enterStage.setAttribute("data-sc-verify-state", "enter:" + (ep < 0.22 ? Math.round(ep * 100) : 100));
      holdIf(enterStage, isReduced || ep >= 0.22);
    }
  }

  // Keyboard users: tabbing into a pinned act scrolls to the cue that holds the focused control.
  document.addEventListener("focusin", function (e) {
    var cueEl = e.target.closest("[data-sc-cue]");
    var actEl = e.target.closest('[data-sc-act="pin"]');
    if (!cueEl || !actEl) return;
    var spec = (cueEl.getAttribute("data-sc-cue") || "").trim().split(/\s+/).map(Number);
    var targetP = spec.length >= 2 && !isNaN(spec[1]) ? (spec[0] + spec[1]) / 2 : Math.max(0.25, spec[0] || 0);
    var top = actEl.getBoundingClientRect().top + window.scrollY;
    var travel = Math.max(0, actEl.offsetHeight - window.innerHeight);
    if (travel > 0) window.scrollTo({ top: Math.round(top + travel * targetP), behavior: "instant" });
  });

  syncScrollDrivenStages();
  var ticking = false;
  function requestTick() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () { ticking = false; syncScrollDrivenStages(); });
  }
  window.addEventListener("scroll", requestTick, { passive: true });
  window.addEventListener("resize", requestTick, { passive: true });
  setInterval(syncScrollDrivenStages, 120);
})();
